-- V21 — outbound Wave 2a: new fields + Dispatch missing fields + Weighment First/Second/Third + tanker seal-lock.

ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS seal_lock_status VARCHAR(24) NULL;
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS sealing_no VARCHAR(48) NULL;
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS sealing_supervisor VARCHAR(96) NULL;
INSERT INTO entity_field_registry (id,tenant_id,entity_code,field_code,display_label,data_type,filterable,sortable,searchable,required,widget_kind,options_json) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM entity_field_registry x),-1,'GatePass','seal_lock_status','Seal Lock Status','STRING',1,1,0,0,'select','[{"label": "Auto Lock", "value": "AUTO_LOCK"}, {"label": "Seal No Update", "value": "SEAL_NO_UPDATE"}]' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM entity_field_registry WHERE entity_code='GatePass' AND field_code='seal_lock_status');
INSERT INTO entity_field_registry (id,tenant_id,entity_code,field_code,display_label,data_type,filterable,sortable,searchable,required,widget_kind,options_json) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM entity_field_registry x),-1,'GatePass','sealing_no','Sealing No','STRING',1,1,0,0,'text',NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM entity_field_registry WHERE entity_code='GatePass' AND field_code='sealing_no');
INSERT INTO entity_field_registry (id,tenant_id,entity_code,field_code,display_label,data_type,filterable,sortable,searchable,required,widget_kind,options_json) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM entity_field_registry x),-1,'GatePass','sealing_supervisor','Sealing Supervisor','STRING',1,1,0,0,'text',NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM entity_field_registry WHERE entity_code='GatePass' AND field_code='sealing_supervisor');

UPDATE page_version SET body_json='{"kind": "layout", "schemaVersion": 2, "dataSources": [{"id": "dispatchQueue", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/Dispatch"}], "layout": [{"kind": "Section", "title": "Dispatch Queue (Open)", "fields": [{"kind": "WorkflowQueueList", "persona": "Dispatch", "dataSource": "dispatchQueue", "pageSize": 25, "cardFields": ["vehicleNo", "gpNumber", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Vehicle & Dispatch Details", "fields": [{"kind": "FormField", "type": "select", "name": "vehicleNo", "label": "Vehicle Number", "required": true, "placeholder": "Select vehicle awaiting dispatch entry", "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "vehicleNumbers", "valueField": "vehicle_no", "labelField": "vehicle_no"}, "onChangeFill": {"flowVariantCode": "flow_variant_code", "loadingType": "loading_type", "instanceId": "workflow_instance_id"}}, {"kind": "FormField", "type": "text", "name": "flowVariantCode", "label": "Flow Variant", "disabled": true}, {"kind": "FormField", "type": "text", "name": "loadingType", "label": "Loading Type", "disabled": true}, {"kind": "FormField", "type": "text", "name": "instanceId", "label": "Workflow Instance", "disabled": true}, {"kind": "FormField", "type": "select", "name": "ownershipType", "label": "Ownership", "options": ["OWN VEHICLE", "HIRED VEHICLE"]}, {"kind": "FormField", "type": "text", "name": "driverName", "label": "Driver Name"}, {"kind": "FormField", "type": "text", "name": "driverPhone", "label": "Driver Contact"}, {"kind": "FormField", "type": "text", "name": "brokerName", "label": "Broker Details", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "text", "name": "invoiceNo", "label": "Invoice No", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "number", "name": "invoiceQty", "label": "Invoice Qty", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "text", "name": "vendorName", "label": "Vendor Details", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "text", "name": "oilRmItem", "label": "Oil RM Details", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "text", "name": "tankerNo", "label": "Tanker Number", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "select", "name": "poVerified", "label": "PO Verified", "options": ["YES", "NO - MANAGER APPROVAL"], "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "text", "name": "poOverrideReason", "label": "Reason (if PO not verified)", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' && #form.poVerified != \'YES\'", "requiredWhen": "#form.flowVariantCode == \'M10.TankerOutbound\' && #form.poVerified != \'YES\'"}, {"kind": "FormField", "type": "text", "name": "dispatchOfficerName", "label": "Dispatch Front Officer Name", "visibleWhen": "#form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "text", "name": "transportName", "label": "Transport Name", "visibleWhen": "#form.flowVariantCode == \'M10.PackLoading\' || #form.flowVariantCode == \'M10.FGLoading\' || #form.flowVariantCode == \'M10.TankerOutbound\'"}, {"kind": "FormField", "type": "textarea", "name": "packingFgStockDetails", "label": "Packing / FG Stock Details", "visibleWhen": "#form.flowVariantCode == \'M10.PackLoading\' || #form.flowVariantCode == \'M10.FGLoading\'"}, {"kind": "WorkflowActionButton", "label": "Save Vehicle Details", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "variant": "primary"}, {"kind": "FormField", "name": "vehicleCategory", "label": "Vehicle Category", "type": "select", "options": [{"label": "Own Vehicle", "value": "OWN"}, {"label": "Hired", "value": "HIRED"}, {"label": "