UPDATE page_version SET body_json='{"kind": "layout", "schemaVersion": 2, "slug": "aria:weighment-capture", "title": "Weighment Capture", "status": "published", "version": 1, "roles": ["WeighmentOfficer", "Manager", "TenantAdmin"], "dataSources": [], "streams": [], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Vehicle & Weighbridge", "span": 12, "subtitle": "One weighment per direction. Loaded weight on entry, empty on exit; difference = quantity received/dispatched.", "children": [{"kind": "Form", "submitLabel": "", "bindings": {"fields": [{"name": "gp_number", "label": "Gate Pass # (from queue)", "type": "text", "required": true, "readOnly": true}, {"name": "vehicle_no", "label": "Vehicle (auto-fill)", "type": "text", "readOnly": true}, {"name": "weighbridge_code", "label": "Weighbridge", "type": "select", "required": true, "options": [{"label": "WB-1 (Main Gate, 60T)", "value": "WB-1"}, {"label": "WB-2 (Dispatch, 40T)", "value": "WB-2"}]}, {"name": "weighment_date", "label": "Date", "type": "date", "required": true}, {"name": "entry_time", "label": "Entry Time", "type": "time", "required": true}, {"name": "weight_officer", "label": "Weighment Officer Name", "type": "text", "required": true}]}}]}, {"kind": "Section", "title": "Reading", "span": 12, "subtitle": "Live feed from the weighbridge controller. Press Capture to lock the reading.", "children": [{"kind": "Form", "submitLabel": "", "bindings": {"fields": [{"name": "weight_seq", "label": "Weighment", "type": "select", "required": true, "options": [{"label": "First (loaded / gross)", "value": "FIRST"}, {"label": "Second (empty / tare)", "value": "SECOND"}, {"label": "Third (re-check)", "value": "THIRD"}]}, {"kind": "FormField", "name": "seal_lock_status", "label": "Seal Lock Status (2nd tanker weight)", "type": "select", "options": [{"label": "Auto Lock", "value": "AUTO_LOCK"}, {"label": "Seal No Update", "value": "SEAL_NO_UPDATE"}], "visibleWhen": "#form.weight_seq == \'SECOND\' && #form.flow_variant_code_hidden == \'M10.TankerOutbound\'"}, {"name": "live_reading_display", "label": "Live Reading", "type": "text", "readOnly": true, "helperText": "Locked while stabilising — wait for the green tick on the controller"}, {"name": "gross_kg", "label": "Gross Weight (kg)", "type": "number", "required": true}, {"name": "tare_kg", "label": "Tare (kg) — from vehicle master or this empty reading", "type": "number"}, {"name": "net_kg", "label": "Net (kg) — auto Gross − Tare", "type": "number", "readOnly": true}, {"name": "expected_kg", "label": "Expected (kg) — from PO / SO", "type": "number", "readOnly": true}, {"name": "variance_kg", "label": "Variance (kg) — auto", "type": "number", "readOnly": true}, {"name": "within_tolerance", "label": "Within Tolerance?", "type": "select", "required": true, "options": [{"label": "YES — proceed", "value": "YES"}, {"label": "NO — route to manager", "value": "NO"}]}, {"kind": "FormField", "name": "flow_variant_code_hidden", "label": "", "type": "text", "readOnly": true}]}}]}, {"kind": "Section", "title": "Photo Evidence", "span": 12, "children": [{"kind": "Form", "submitLabel": "", "bindings": {"fields": [{"name": "wb_display_photo", "label": "Weighbridge Display Photo", "type": "file", "accept": "image/*"}, {"name": "vehicle_photo", "label": "Vehicle on Bridge Photo", "type": "file", "accept": "image/*"}, {"name": "notes", "label": "Notes (any anomaly)", "type": "textarea", "rows": 2}]}}]}, {"kind": "Section", "span": 12, "children": [{"kind": "WorkflowActionButton", "action": "workflow.transition", "label": "Capture & Save Weighment", "variant": "primary"}]}]}]}' WHERE id=5;
